drop policy if exists "schedule_events: client read own" on schedule_events; create policy "schedule_events: client read own" on schedule_events for select using ( public.current_role() = 'client' and client_id is not null and client_id = public.current_client_id() ); create table if not exists notifications ( id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles (id) on delete cascade, kind text not null, title text not null, body text, href text, read boolean not null default false, email_pending boolean not null default false, email_sent_at timestamptz, created_at timestamptz not null default now() ); create index if not exists notifications_user_unread_idx on notifications (user_id, read, created_at desc); create index if not exists notifications_email_pending_idx on notifications (email_pending) where email_pending; alter table notifications enable row level security; drop policy if exists "notifications: own rows" on notifications; create policy "notifications: own rows" on notifications for select using (user_id = auth.uid()); drop policy if exists "notifications: mark own read" on notifications; create policy "notifications: mark own read" on notifications for update using (user_id = auth.uid()) with check (user_id = auth.uid()); create or replace function public.notify_user( target_user_id uuid, notification_kind text, notification_title text, notification_body text default null, notification_href text default null, wants_email boolean default true ) returns void language plpgsql security definer set search_path = public as $$ begin if target_user_id is null then return; end if; if target_user_id = auth.uid() then return; end if; insert into public.notifications (user_id, kind, title, body, href, email_pending) values (target_user_id, notification_kind, notification_title, notification_body, notification_href, wants_email); end; $$; create or replace function public.notify_client_assignment() returns trigger language plpgsql security definer set search_path = public as $$ declare client_name text; begin select name into client_name from public.clients where id = new.client_id; perform public.notify_user( new.staff_id, 'client_assigned', 'You have been added to ' || coalesce(client_name, 'a client'), 'Their brand kit, content plan and documents are on their page.', '/app/my-clients/' || new.client_id::text ); return new; end; $$; drop trigger if exists client_staff_notify on client_staff; create trigger client_staff_notify after insert on client_staff for each row execute procedure public.notify_client_assignment(); create or replace function public.notify_task_change() returns trigger language plpgsql security definer set search_path = public as $$ declare client_name text; due_text text; begin if new.assigned_to is null then return new; end if; if new.client_id is not null then select name into client_name from public.clients where id = new.client_id; end if; due_text := case when new.due_date is null then null else 'Due ' || to_char(new.due_date, 'FMDD FMMonth') end; if tg_op = 'INSERT' then perform public.notify_user( new.assigned_to, 'task_assigned', 'New task: ' || new.text, concat_ws(' · ', client_name, due_text), '/app/my-work' ); return new; end if; if new.assigned_to is distinct from old.assigned_to then perform public.notify_user( new.assigned_to, 'task_assigned', 'A task was passed to you: ' || new.text, concat_ws(' · ', client_name, due_text), '/app/my-work' ); elsif new.due_date is distinct from old.due_date then perform public.notify_user( new.assigned_to, 'task_deadline_changed', 'Deadline changed: ' || new.text, case when new.due_date is null then 'The due date was removed.' else due_text end, '/app/my-work' ); elsif new.text is distinct from old.text then perform public.notify_user( new.assigned_to, 'task_updated', 'A task of yours was reworded', new.text, '/app/my-work' ); end if; return new; end; $$; drop trigger if exists tasks_notify on tasks; create trigger tasks_notify after insert or update on tasks for each row execute procedure public.notify_task_change(); alter table submissions add column if not exists visibility text not null default 'team_only' check (visibility in ('team_only', 'team_and_client')), add column if not exists planner_slot_id text; do $$ declare orphans integer; begin select count(*) into orphans from public.submissions where client_id is null; if orphans = 0 then alter table public.submissions alter column client_id set not null; raise notice 'submissions.client_id is now NOT NULL.'; else raise warning 'submissions.client_id left nullable: % existing row(s) have no client. Set a client on them from the admin side, then re-run this migration to apply the constraint.', orphans; end if; end $$; drop policy if exists "submissions: client read shared" on submissions; create policy "submissions: client read shared" on submissions for select using ( public.current_role() = 'client' and visibility = 'team_and_client' and client_id is not null and client_id = public.current_client_id() ); drop policy if exists "submission_versions: client read shared" on submission_versions; create policy "submission_versions: client read shared" on submission_versions for select using ( public.current_role() = 'client' and exists ( select 1 from public.submissions s where s.id = submission_id and s.visibility = 'team_and_client' and s.client_id = public.current_client_id() ) ); create table if not exists portfolio_items ( id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references profiles (id) on delete cascade, title text not null, url text, client_id uuid references clients (id) on delete set null, client_label text, completed_on date, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); alter table portfolio_items alter column owner_id set default auth.uid(); create index if not exists portfolio_items_owner_idx on portfolio_items (owner_id, completed_on desc); alter table portfolio_items enable row level security; drop policy if exists "portfolio_items: own rows" on portfolio_items; create policy "portfolio_items: own rows" on portfolio_items for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); drop policy if exists "portfolio_items: management read" on portfolio_items; create policy "portfolio_items: management read" on portfolio_items for select using (public.is_management()); drop trigger if exists portfolio_items_touch on portfolio_items; create trigger portfolio_items_touch before update on portfolio_items for each row execute procedure public.touch_updated_at(); create table if not exists team_channel_messages ( id uuid primary key default gen_random_uuid(), channel text not null default 'videographers', author_id uuid not null references profiles (id) on delete cascade, body text not null, created_at timestamptz not null default now() ); create index if not exists team_channel_messages_idx on team_channel_messages (channel, created_at); alter table team_channel_messages enable row level security; drop policy if exists "team_channel_messages: read" on team_channel_messages; create policy "team_channel_messages: read" on team_channel_messages for select using ( channel = 'videographers' and public.current_role() in ('videographer', 'staff', 'operations_manager', 'ceo') ); drop policy if exists "team_channel_messages: post as self" on team_channel_messages; create policy "team_channel_messages: post as self" on team_channel_messages for insert with check ( channel = 'videographers' and author_id = auth.uid() and public.current_role() in ('videographer', 'staff', 'operations_manager', 'ceo') );
